#nullable enable // autogenerated

using MVZ2.GameContent.Bosses;
using MVZ2.Vanilla.Detections;
using MVZ2.Vanilla.Entities;
using MVZ2.Vanilla.Level;
using MVZ2Logic.Entities;
using PVZEngine.Collisions;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Models;
using PVZEngine.Tools;
using UnityEngine;

namespace MVZ2.GameContent.Effects
{
    [AutoEntityBehaviourDefinition(VanillaEffectNames.risingIcePillar)]
    public class RisingIcePillar : EntityBehaviourDefinition
    {
        public RisingIcePillar(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);

            using var krakensItem = ListPool<Entity>.Rent();
            var krakens = krakensItem.Value;
            krakenDetector.DetectEntities(entity, krakens);

            bool stunned = false;
            foreach (var kraken in krakens)
            {
                if (!Kraken.CanStun(kraken))
                    continue;
                Kraken.Stun(kraken, Kraken.STUN_SECONDS);
                stunned = true;
            }
            if (stunned)
            {
                Kraken.PlayCriticalEffects(entity, entity.Position);
            }
        }
        private static readonly Detector krakenDetector = new KrakenDetector()
        {
            canDetectInvisible = true,
            factionTarget = FactionTarget.Any
        };

        public class KrakenDetector : Detector
        {
            protected override Bounds GetDetectionBounds(Entity self)
            {
                return self.GetBounds();
            }
            public override bool ValidateTarget(DetectionParams self, Entity target)
            {
                if (!target.IsEntityOf(VanillaBossID.kraken))
                    return false;
                return base.ValidateTarget(self, target);
            }
            protected override bool ValidateCollider(DetectionParams param, IEntityCollider collider)
            {
                if (!collider.IsForMain())
                    return false;
                return base.ValidateCollider(param, collider);
            }
        }
    }
}